// auditlog — tamper-evident hash-chained log
// Hash: sha256

fn open_log::(path) {
    if (@exists(path)) {
        let lines = @read_lines(path);
        let entries = [];
        for line in lines {
            if (@str_is_blank(line)) { continue; }
            @push(entries, @json_decode(line));
        }
        return {"path": path, "entries": entries};
    }
    return {"path": path, "entries": []};
}

fn hash_entry::(prev_hash, payload) {
    let blob = @bytes(prev_hash + "|" + @json_encode(payload));
    return @sha256_hex(blob);
}

fn append_entry::(log, event_type, data) {
    let entries = log["entries"];
    let prev_hash = @len(entries) > 0 ? entries[@len(entries) - 1]["hash"] : "0000000000000000";
    let payload = {"ts": @now_iso(), "seq": @len(entries), "type": event_type, "data": data};
    let entry = {"prev": prev_hash, "payload": payload, "hash": hash_entry(prev_hash, payload)};
    @push(entries, entry);
    @append_text(log["path"], @json_encode(entry) + "\n");
    return entry["hash"];
}

fn verify_chain::(log) {
    let entries = log["entries"];
    let prev = "0000000000000000";
    for i in @range(0, @len(entries)) {
        let e = entries[i];
        if (e["prev"] != prev) { return {"ok": false, "at": i, "reason": "prev mismatch"}; }
        let expected = hash_entry(prev, e["payload"]);
        if (expected != e["hash"]) { return {"ok": false, "at": i, "reason": "hash mismatch"}; }
        prev = e["hash"];
    }
    return {"ok": true, "length": @len(entries)};
}

fn find_by_type::(log, t) {
    let out = [];
    for e in log["entries"] { if (e["payload"]["type"] == t) { @push(out, e); } }
    return out;
}

fn tail::(log, n) {
    let entries = log["entries"];
    let total = @len(entries);
    let start = total > n ? total - n : 0;
    let out = [];
    for i in @range(start, total) { @push(out, entries[i]); }
    return out;
}

fn count_of::(log) { return @len(log["entries"]); }
fn version::() { return "1.0.0"; }
